ed]",["zh-cn"]="【房主禁用】",["zh-tw"]="【房主禁用】"},["diy_host_rules"]={["en"]="Host rules",["zh-cn"]="房主规则",["zh-tw"]="房主規則"},["diy_host_rules_help"]={["en"]="Native talents use one global pool switch. Manage individual DIY permissions in the unified talent pool.",["zh-cn"]="原生技能仅有池子整体开关。DIY 单项权限在统一天赋池中管理。",["zh-tw"]="原生技能僅有池子整體開關。DIY 單項權限在統一天賦池中管理。"},["diy_identifier_invalid"]={["en"]="Paste an ID containing only letters, digits, _ and - (up to 64 characters).",["zh-cn"]="请粘贴仅含字母、数字、下划线和连字符的 ID（最多 64 字符）。",["zh-tw"]="請粘貼僅含字母、數字、下劃線和連字符的 ID（最多 64 字符）。"},["diy_in_pool"]={["en"]="Available for this character in this room",["zh-cn"]="当前角色可在本房间获得",["zh-tw"]="當前角色可在本房間獲得"},["diy_incompatible"]={["en"]="Unavailable for this build; excluded from selection.",["zh-cn"]="不适用于当前配装，已排除抽取。",["zh-tw"]="不適用於當前配裝，已排除抽取。"},["diy_language"]={["en"]="en",["zh-cn"]="zh-cn",["zh-tw"]="zh-tw"},["diy_library_explanation"]={["en"]="Packages load at startup. Refresh after adding or editing a package in game; changes apply next mission. Mortis requires matching JSON, Lua, resources and dependencies across the room.",["zh-cn"]="包在启动时自动载入。游戏中新增或修改后刷新，更新用于下一局。死灵入池要求房内玩家的 JSON、Lua、资源及依赖一致。",["zh-tw"]="包在啓動時自動載入。遊戲中新增或修改後刷新，更新用於下一局。死靈入池要求房內玩家的 JSON、Lua、資源及依賴一致。"},["diy_library_settings"]={["en"]="Package manager",["zh-cn"]="包管理",["zh-tw"]="包管理"},["diy_load"]={["en"]="Load file",["zh-cn"]="载入文件",["zh-tw"]="載入文件"},["diy_manual"]={["en"]="Manual selection",["zh-cn"]="手动选择",["zh-tw"]="手動選擇"},["diy_mode_summary"]={["en"]="Up to %s reward rounds · inspect any talent below · native family first when the native pool is on",["zh-cn"]="最多 %s 轮奖励 · 可随时查看技能与入池状态 · 原生池开启时先选原生流派",["zh-tw"]="最多 %s 輪獎勵 · 可隨時查看技能與入池狀態 · 原生池開啓時先選原生流派"},["diy_native_limit"]={["en"]="Reward limit: ",["zh-cn"]="奖励上限：",["zh-tw"]="獎勵上限："},["diy_native_weight"]={["en"]="Native opening families use native rules. Mixed talent draws give each native candidate weight 1.",["zh-cn"]="开局流派遵循原生规则。混合技能抽选中，每个原生候选的权重为 1。",["zh-tw"]="開局流派遵循原生規則。混合技能抽選中，每個原生候選的權重爲 1。"},["diy_native_whole_only"]={["en"]="Only DIY talents support individual room permissions. The native pool can only be enabled or disabled as a whole.",["zh-cn"]="房间内仅 DIY 技能支持逐项管理。原生死灵池只能整体开启或关闭。",["zh-tw"]="房間內僅 DIY 技能支持逐項管理。原生死靈池只能整體開啓或關閉。"},["diy_native_whole_only_short"]={["en"]="Native talents use the pool’s global switch.",["zh-cn"]="原生技能仅使用池子整体开关。",["zh-tw"]="原生技能僅使用池子整體開關。"},["diy_need_ability"]={["en"]="Requires a specific combat ability.",["zh-cn"]="当前战斗技能不符合要求。",["zh-tw"]="當前戰鬥技能不符合要求。"},["diy_need_ammo"]={["en"]="Requires an equipped weapon that uses ammunition.",["zh-cn"]="需要装备使用弹药的武器。",["zh-tw"]="需要裝備使用彈藥的武器。"},["diy_need_archetype"]={["en"]="Requires a different archetype.",["zh-cn"]="当前职业不符合要求。",["zh-tw"]="當前職業不符合要求。"},["diy_need_blitz"]={["en"]="Requires a specific Blitz ability.",["zh-cn"]="当前闪击不符合要求。",["zh-tw"]="當前閃擊不符合要求。"},["diy_need_combat_ability"]={["en"]="Requires a combat ability with a cooldown.",["zh-cn"]="需要具有冷却时间的战斗技能。",["zh-tw"]="需要具有冷卻時間的戰鬥技能。"},["diy_need_family"]={["en"]="Requires a different Mortis route.",["zh-cn"]="当前死灵流派不符合要求。",["zh-tw"]="當前死靈流派不符合要求。"},["diy_need_grenade_charges"]={["en"]="Requires a Blitz that uses charges.",["zh-cn"]="需要使用次数型充能的闪击。",["zh-tw"]="需要使用次數型充能的閃擊。"},["diy_need_hcm"]={["en"]="Pausing native spawns needs Havoc Condition Manager.",["zh-cn"]="暂停原生刷新需要 Havoc Condition Manager。",["zh-tw"]="暫停原生刷新需要 Havoc Condition Manager。"},["diy_need_hed"]={["en"]="Selected spawns need Havoc Enemy Director and an enabled director.",["zh-cn"]="所选生成动作需要 HED，并需启用其导演调度。",["zh-tw"]="所選生成動作需要 HED，並需啓用其導演調度。"},["diy_need_melee"]={["en"]="Requires an equipped melee weapon.",["zh-cn"]="需要装备近战武器。",["zh-tw"]="需要裝備近戰武器。"},["diy_need_overheat"]={["en"]="Requires a weapon with an overheat system.",["zh-cn"]="需要装备具有过热系统的武器。",["zh-tw"]="需要裝備具有過熱系統的武器。"},["diy_need_ranged"]={["en"]="Requires an equipped ranged weapon.",["zh-cn"]="需要装备远程武器。",["zh-tw"]="需要裝備遠程武器。"},["diy_need_reload"]={["en"]="Requires a weapon with a native reload action.",["zh-cn"]="需要装备具有原生换弹动作的武器。",["zh-tw"]="需要裝備具有原生換彈動作的武器。"},["diy_need_resources"]={["en"]="None of the required resources are available.",["zh-cn"]="当前配装不具备所需的任一资源。",["zh-tw"]="當前配裝不具備所需的任一資源。"},["diy_need_talents"]={["en"]="Requires selected character talents.",["zh-cn"]="尚未选取要求的角色天赋。",["zh-tw"]="尚未選取要求的角色天賦。"},["diy_need_warp_charge"]={["en"]="Requires the Peril resource.",["zh-cn"]="需要角色具有危机值资源。",["zh-tw"]="需要角色具有危機值資源。"},["diy_need_weapon"]={["en"]="Requires a compatible equipped weapon.",["zh-cn"]="需要装备符合要求的武器。",["zh-tw"]="需要裝備符合要求的武器。"},["diy_network_build_pending"]={["en"]="Host is waiting for your build data.",["zh-cn"]="房主正在等待你的配装资料。",["zh-tw"]="房主正在等待你的配裝資料。"},["diy_network_config_mismatch"]={["en"]="Host and client libraries differ",["zh-cn"]="房主与客机配置库不同",["zh-tw"]="房主與客機配置庫不同"},["diy_network_disconnected"]={["en"]="Host synchronization expired",["zh-cn"]="房主同步已过期",["zh-tw"]="房主同步已過期"},["diy_network_host_disabled"]={["en"]="Host DIY is disabled",["zh-cn"]="房主未启用 DIY",["zh-tw"]="房主未啓用 DIY"},["diy_network_incompatible_selection"]={["en"]="Host rejected entries incompatible with your build.",["zh-cn"]="房主已拒绝与你的配装不适配的条目。",["zh-tw"]="房主已拒絕與你的配裝不適配的條目。"},["diy_network_invalid_selection"]={["en"]="Host rejected the selection",["zh-cn"]="房主拒绝了所选条目",["zh-tw"]="房主拒絕了所選條目"},["diy_network_offline"]={["en"]="Local / waiting for host",["zh-cn"]="本地／等待房主",["zh-tw"]="本地／等待房主"},["diy_network_policy_pending"]={["en"]="Waiting for host talent rules",["zh-cn"]="等待房主同步天赋规则",["zh-tw"]="等待房主同步天賦規則"},["diy_network_ready"]={["en"]="Host approved",["zh-cn"]="房主已确认",["zh-tw"]="房主已確認"},["diy_next"]={["en"]="Next",["zh-cn"]="下一页",["zh-tw"]="下一頁"},["diy_no_clipboard"]={["en"]="Clipboard text is unavailable.",["zh-cn"]="无法读取剪贴板文本。",["zh-tw"]="無法讀取剪貼板文本。"},["diy_no_files"]={["en"]="No package folders found",["zh-cn"]="未发现包文件夹",["zh-tw"]="未發現包文件夾"},["diy_not_in_pool"]={["en"]="Not currently in this character’s pool",["zh-cn"]="当前不在此角色的候选池内",["zh-tw"]="當前不在此角色的候選池內"},["diy_number_error"]={["en"]="Enter an integer from 0 to %s.",["zh-cn"]="请输入 0 至 %s 的整数。",["zh-tw"]="請輸入 0 至 %s 的整數。"},["diy_number_help"]={["en"]="DIY points: 0–99. Enter confirms; Esc cancels.",["zh-cn"]="DIY 点数：0–99。回车确认，Esc 取消。",["zh-tw"]="DIY 點數：0–99。回車確認，Esc 取消。"},["diy_number_typing"]={["en"]="Value: %s | Enter to confirm, Esc to cancel (0–%s).",["zh-cn"]="数值：%s | 回车确认，Esc 取消（0–%s）。",["zh-tw"]="數值：%s | 回車確認，Esc 取消（0–%s）。"},["diy_package_changed"]={["en"]="A package file changed while being read. Refresh again after saving.",["zh-cn"]="读取期间包文件发生变化，请保存完成后重新刷新。",["zh-tw"]="讀取期間包文件發生變化，請保存完成後重新刷新。"},["diy_package_disable"]={["en"]="Disable package",["zh-cn"]="停用此包",["zh-tw"]="停用此包"},["diy_package_disabled"]={["en"]="Package disabled",["zh-cn"]="此包已停用",["zh-tw"]="此包已停用"},["diy_package_enable"]={["en"]="Enable package",["zh-cn"]="启用此包",["zh-tw"]="啓用此包"},["diy_package_exists"]={["en"]="The package already exists and has been preserved.",["zh-cn"]="包已存在，已保留原文件。",["zh-tw"]="包已存在，已保留原文件。"},["diy_package_io"]={["en"]="Unable to read or write the package directory.",["zh-cn"]="无法读写包目录。",["zh-tw"]="無法讀寫包目錄。"},["diy_package_limit"]={["en"]="Package count or size limit exceeded.",["zh-cn"]="包数量、文件数量或大小超过限制。",["zh-tw"]="包數量、文件數量或大小超過限制。"},["diy_package_missing"]={["en"]="Package unavailable. Check the selected package error.",["zh-cn"]="包不可用，请查看此包的错误。",["zh-tw"]="包不可用，請查看此包的錯誤。"},["diy_package_path"]={["en"]="Invalid package folder/path or directory link.",["zh-cn"]="包目录或路径不合法，或包含目录链接。",["zh-tw"]="包目錄或路徑不合法，或包含目錄鏈接。"},["diy_packages_count"]={["en"]="Loaded %d / %d packages · %d entries · %d errors",["zh-cn"]="已载入 %d / %d 个包 · %d 项条目 · %d 个错误",["zh-tw"]="已載入 %d / %d 個包 · %d 項條目 · %d 個錯誤"},["diy_packages_exported"]={["en"]="Complete packages exported to: %s",["zh-cn"]="完整包已导出至：%s",["zh-tw"]="完整包已導出至：%s"},["diy_packages_refreshed"]={["en"]="Packages refreshed; mission content remains frozen.",["zh-cn"]="包已刷新；当前任务内容保持不变。",["zh-tw"]="包已刷新；當前任務內容保持不變。"},["diy_page_summary"]={["en"]="Page %s / %s  ·  %s talents",["zh-cn"]="第 %s / %s 页  ·  %s 项技能",["zh-tw"]="第 %s / %s 頁  ·  %s 項技能"},["diy_paste"]={["en"]="Paste JSON",["zh-cn"]="粘贴 JSON",["zh-tw"]="粘貼 JSON"},["diy_paste_identifier"]={["en"]="Click to paste an identifier",["zh-cn"]="点击粘贴标识符",["zh-tw"]="點擊粘貼標識符"},["diy_peer_different"]={["en"]="Different definition / weight",["zh-cn"]="定义或权重不一致",["zh-tw"]="定義或權重不一致"},["diy_peer_disabled"]={["en"]="Manager disabled",["zh-cn"]="管理器已停用",["zh-tw"]="管理器已停用"},["diy_peer_disconnected"]={["en"]="Installation confirmation expired",["zh-cn"]="安装确认已过期",["zh-tw"]="安裝確認已過期"},["diy_peer_missing"]={["en"]="Unavailable until every player has this DIY definition.",["zh-cn"]="需房间内所有玩家具备一致的 DIY 定义后才能入池。",["zh-tw"]="需房間內所有玩傢俱備一致的 DIY 定義後才能入池。"},["diy_peer_missing_entry"]={["en"]="Missing this DIY talent",["zh-cn"]="缺少此 DIY 技能",["zh-tw"]="缺少此 DIY 技能"},["diy_peer_pending"]={["en"]="Waiting for installation confirmation",["zh-cn"]="等待安装确认",["zh-tw"]="等待安裝確認"},["diy_peer_unconfirmed"]={["en"]="DIY installation not confirmed",["zh-cn"]="未确认安装 DIY",["zh-tw"]="未確認安裝 DIY"},["diy_points_help"]={["en"]="One point per talent. Tier is a label; draws follow pool membership and weight.",["zh-cn"]="每项天赋消耗 1 点。等级仅为标签，抽选按入池状态与权重决定。",["zh-tw"]="每項天賦消耗 1 點。等級僅爲標籤，抽選按入池狀態與權重決定。"},["diy_points_limit"]={["en"]="DIY point limit",["zh-cn"]="DIY 点数上限",["zh-tw"]="DIY 點數上限"},["diy_policy_allowed"]={["en"]="Allowed in this session",["zh-cn"]="本房间允许使用",["zh-tw"]="本房間允許使用"},["diy_policy_clear_search"]={["en"]="Clear search",["zh-cn"]="清除搜索",["zh-tw"]="清除搜索"},["diy_policy_diy"]={["en"]="DIY talents",["zh-cn"]="DIY 天赋",["zh-tw"]="DIY 天賦"},["diy_policy_empty"]={["en"]="No matching talents",["zh-cn"]="没有匹配的天赋",["zh-tw"]="沒有匹配的天賦"},["diy_policy_locked"]={["en"]="Rules are locked for this mission. Edit them in the hub before the next mission.",["zh-cn"]="本局规则已锁定，请返回大厅后修改下一局规则。",["zh-tw"]="本局規則已鎖定，請返回大廳後修改下一局規則。"},["diy_policy_native"]={["en"]="Native talents",["zh-cn"]="原生天赋",["zh-tw"]="原生天賦"},["diy_policy_pending"]={["en"]="Waiting for host talent rules.",["zh-cn"]="等待房主同步天赋规则。",["zh-tw"]="等待房主同步天賦規則。"},["diy_policy_saved"]={["en"]="Saved automatically. These rules apply to everyone in your room. Only affected selections receive a notice.",["zh-cn"]="自动保存并应用于房间内所有玩家；仅提示已预选或持有禁用天赋的玩家。",["zh-tw"]="自動保存並應用於房間內所有玩家；僅提示已預選或持有禁用天賦的玩家。"},["diy_policy_search"]={["en"]="Search (paste): ",["zh-cn"]="搜索（粘贴）：",["zh-tw"]="搜索（粘貼）："},["diy_pool_closed"]={["en"]="This talent’s source pool is switched off.",["zh-cn"]="此技能所属的池子已整体关闭。",["zh-tw"]="此技能所屬的池子已整體關閉。"},["diy_pool_short"]={["en"]="Available",["zh-cn"]="可入池",["zh-tw"]="可入池"},["diy_preselection_summary"]={["en"]="My preselection · Native %s / %s · DIY points %s / %s",["zh-cn"]="我的预选 · 原生 %s / %s · DIY 点数 %s / %s",["zh-tw"]="我的預選 · 原生 %s / %s · DIY 點數 %s / %s"},["diy_preview"]={["en"]="Next mission: ",["zh-cn"]="下一局：",["zh-tw"]="下一局："},["diy_random"]={["en"]="Weighted draw",["zh-cn"]="加权抽取",["zh-tw"]="加權抽取"},["diy_ready"]={["en"]="Validated · ready for the next mission",["zh-cn"]="校验通过 · 下一局生效",["zh-tw"]="校驗通過 · 下一局生效"},["diy_remove_preselection"]={["en"]="Remove my preselection",["zh-cn"]="移出我的预选",["zh-tw"]="移出我的預選"},["diy_reward_candidate"]={["en"]="Awarded through mission rewards",["zh-cn"]="通过本局奖励获得",["zh-tw"]="通過本局獎勵獲得"},["diy_reward_settings"]={["en"]="Reward settings",["zh-cn"]="奖励设置",["zh-tw"]="獎勵設置"},["diy_reward_settings_help"]={["en"]="In Realms, the host can edit these limits in the Mortis preparation controls. SoloPlay can edit them here. Use minus/plus, or click the number to type it. Progress keeps ten reward rounds.",["zh-cn"]="Realms 房主可在准备界面的死灵天赋控件中调整上限，SoloPlay 可在此调整。使用加减号，或点击数字直接输入。进度模式保持十轮奖励。",["zh-tw"]="Realms 房主可在準備界面的死靈天賦控件中調整上限，SoloPlay 可在此調整。使用加減號，或點擊數字直接輸入。進度模式保持十輪獎勵。"},["diy_room_browsing"]={["en"]="Browse talents and room availability",["zh-cn"]="浏览技能与房间可用状态",["zh-tw"]="瀏覽技能與房間可用狀態"},["diy_room_editing"]={["en"]="Host · preparing this room",["zh-cn"]="房主 · 房间准备中",["zh-tw"]="房主 · 房間準備中"},["diy_rules"]={["en"]="Rules: ",["zh-cn"]="事件规则：",["zh-tw"]="事件規則："},["diy_scan"]={["en"]="Refresh packages",["zh-cn"]="刷新包",["zh-tw"]="刷新包"},["diy_search_input"]={["en"]="Search: ",["zh-cn"]="搜索：",["zh-tw"]="搜索："},["diy_seed"]={["en"]="Seed (click to paste): ",["zh-cn"]="种子（点击粘贴）：",["zh-tw"]="種子（點擊粘貼）："},["diy_seed_back"]={["en"]="‹ Overall settings",["zh-cn"]="‹ 返回整体调节",["zh-tw"]="‹ 返回整體調節"},["diy_seed_conditions_help"]={["en"]="Off: ignore the saved value and use the mission seed, or generate one if unavailable. On: use the full integer entered above (1–2147483646). This controls chance checks and Lua random streams inside active conditions, not which conditions are enabled.",["zh-cn"]="关闭：忽略保存值，使用本局任务种子；任务未提供种子时生成随机值。开启：使用上方输入的完整整数（1–2147483646）。此种子影响已启用词条内的概率判定和 Lua 随机流，不决定启用哪些词条。",["zh-tw"]="關閉：忽略保存值，使用本局任務種子；任務未提供種子時生成隨機值。開啓：使用上方輸入的完整整數（1–2147483646）。此種子影響已啓用詞條內的概率判定和 Lua 隨機流，不決定啓用哪些詞條。"},["diy_seed_fixed_conditions"]={["en"]="Use a fixed condition-event seed",["zh-cn"]="启用固定词条事件种子",["zh-tw"]="啓用固定詞條事件種子"},["diy_seed_invalid"]={["en"]="Copy an integer from 1 to 2147483646, then click Seed.",["zh-cn"]="请复制 1 至 2147483646 的整数，再点击种子。",["zh-tw"]="請複製 1 至 2147483646 的整數，再點擊種子。"},["diy_seed_next_mission"]={["en"]="Changes apply next mission. Turning a switch off keeps the saved number for later use. Matching seeds require matching inputs to reproduce a sequence.",["zh-cn"]="修改用于下一局。关闭开关会保留输入值，供下次开启使用；复现随机序列还需要相同的输入条件。",["zh-tw"]="修改用於下一局。關閉開關會保留輸入值，供下次開啓使用；復現隨機序列還需要相同的輸入條件。"},["diy_seed_other_scopes"]={["en"]="HED has separate switches for director deployments and the native roamer layout. Other native combat randomness keeps its own behavior.",["zh-cn"]="HED 分别提供导演部署与原生驻军布局的种子开关；其他原生战斗随机过程保持各自行为。",["zh-tw"]="HED 分別提供導演部署與原生駐軍佈局的種子開關；其他原生戰鬥隨機過程保持各自行爲。"},["diy_seed_settings"]={["en"]="Random seeds",["zh-cn"]="随机种子",["zh-tw"]="隨機種子"},["diy_seed_value"]={["en"]="Seed value",["zh-cn"]="种子数值",["zh-tw"]="種子數值"},["diy_select_filtered"]={["en"]="Select all filtered results",["zh-cn"]="选择全部筛选结果",["zh-tw"]="選擇全部篩選結果"},["diy_selected_short"]={["en"]="Preselected",["zh-cn"]="已预选",["zh-tw"]="已預選"},["diy_selection_full"]={["en"]="Selection limit reached.",["zh-cn"]="已达到选择数量上限。",["zh-tw"]="已達到選擇數量上限。"},["diy_selection_help"]={["en"]="Selections apply next mission. Manage installed folders on the Package manager page.",["zh-cn"]="所选内容用于下一局；安装文件夹请在「包管理」页面操作。",["zh-tw"]="所選內容用於下一局；安裝文件夾請在「包管理」頁面操作。"},["diy_settings_locked"]={["en"]="Room settings lock during missions.",["zh-cn"]="任务中锁定房间配置。",["zh-tw"]="任務中鎖定房間配置。"},["diy_source_diy"]={["en"]="DIY",["zh-cn"]="DIY",["zh-tw"]="DIY"},["diy_source_native"]={["en"]="Native",["zh-cn"]="原生",["zh-tw"]="原生"},["diy_talents"]={["en"]="DIY talents",["zh-cn"]="DIY 天赋",["zh-tw"]="DIY 天賦"},["diy_tier"]={["en"]="Tier ",["zh-cn"]="等级 ",["zh-tw"]="等級 "},["diy_tier_label_help"]={["en"]="Tier is a display label, with no tier cost or quota. Eligible pool entries are drawn by weight.",["zh-cn"]="等级仅作展示标签，不计为点数，也不设等级配额。适配且在池内的条目按权重抽取。",["zh-tw"]="等級僅作展示標籤，不計爲點數，也不設等級配額。適配且在池內的條目按權重抽取。"},["diy_title"]={["en"]="DIY library",["zh-cn"]="DIY 配置库",["zh-tw"]="DIY 配置庫"},["diy_total"]={["en"]="Maximum: ",["zh-cn"]="数量上限：",["zh-tw"]="數量上限："},["diy_unavailable_notice"]={["en"]="These selected talents are unavailable in this room: %s. See Talent pool for the reason.",["zh-cn"]="你已选择的这些技能在本房间暂不可用：%s。可在天赋池详情中查看原因。",["zh-tw"]="你已選擇的這些技能在本房間暫不可用：%s。可在天賦池詳情中查看原因。"},["diy_unavailable_short"]={["en"]="Unavailable",["zh-cn"]="不可入池",["zh-tw"]="不可入池"},["diy_weight"]={["en"]="Draw weight: ",["zh-cn"]="抽选权重：",["zh-tw"]="抽選權重："},["diy_weight_explanation"]={["en"]="Set weight in the JSON template: 1 by default, 0 for manual selection only. During mixed draws each native candidate has weight 1; DIY candidates use their configured weights.",["zh-cn"]="在 JSON 模板中设置 weight：默认 1，设为 0 时仅可预选。混合抽选中，原生候选权重为 1，DIY 候选使用配置权重。",["zh-tw"]="在 JSON 模板中設置 weight：默認 1，設爲 0 時僅可預選。混合抽選中，原生候選權重爲 1，DIY 候選使用配置權重。"},["diy_workspace_title"]={["en"]="Mortis talent pool",["zh-cn"]="死灵天赋池",["zh-tw"]="死靈天賦池"},["diy_zero_weight"]={["en"]="Draw weight is zero; manual preselection remains available.",["zh-cn"]="抽选权重为 0，仅可在预选模式中选择。",["zh-tw"]="抽選權重爲 0，僅可在預選模式中選擇。"}}
